// One backend, one runtime: a client, a store, and the services the
// Druxt modules inject.
const client = new DruxtClient(baseUrl, options)
const store = new Vuex.Store({ state: JSON.parse(JSON.stringify(state)), mutations })
for (const install of [DruxtStore, DruxtRouterStore, DruxtSchemaStore, DruxtMenuStore, DruxtViewsStore]) {
  install({ store })
}
store.$druxt = client
store.$druxtMenu = new DruxtMenu(baseUrl, options)
store.$druxtRouter = () => new DruxtRouter(baseUrl, options)
store.$druxtSchema = { import: schemaImporter(baseUrl, options) }
